mapper.select:
SELECT g.seller_id as seller_id, b.business_name as business_name, SUM(p.payment_amount) as netSales, COUNT(DISTINCT p.order_id) as orderCount, b.commission_rate as commission_rate FROM payment p INNER JOIN userorder u ON p.order_id = u.order_id INNER JOIN goods g ON u.goods_num = g.goods_num INNER JOIN business b ON g.seller_id = b.seller_id WHERE u.delivery_state = 'finished'
AND p.payment_time >= #{beginDate}
AND p.payment_time <= #{endDate}
GROUP BY g.seller_id, b.business_name, b.commission_rate ORDER BY netSales DESC

mapper.update:

UPDATE business
SET commission_rate = #{commission_rate}
WHERE seller_id = #{seller_id}

mapper.select:
SELECT DATE_FORMAT(p.payment_time, '%m-%d') as date, IFNULL(SUM(CASE WHEN u.delivery_state = 'finished' THEN p.payment_amount WHEN u.delivery_state = 'cancel_order' THEN -p.payment_amount ELSE 0 END), 0) as netSales FROM payment p INNER JOIN userorder u ON p.order_id = u.order_id INNER JOIN goods g ON u.goods_num = g.goods_num WHERE g.seller_id = #{seller_id}
AND DATE_FORMAT(p.payment_time, '%Y-%m') = #{selectedMonth}
GROUP BY DATE_FORMAT(p.payment_time, '%Y-%m-%d') ORDER BY date ASC

SELECT DATE_FORMAT(p.payment_time, '%Y-%m-%d %H:%i') as date, p.order_id as order_id, p.payment_amount as amount, u.delivery_state as delivery_state FROM payment p INNER JOIN userorder u ON p.order_id = u.order_id INNER JOIN goods g ON u.goods_num = g.goods_num WHERE g.seller_id = #{seller_id}
AND DATE_FORMAT(p.payment_time, '%Y-%m') = #{selectedMonth}
ORDER BY p.payment_time DESC LIMIT 10
